var motor, ziel, licht, tuerL, tuerR, haube, koffer, fach, fenster, lenkZiel, tempo, lenk;


api.on('start', async () => {
  motor = 0;
  licht = 0;
  tuerL = 0;
  tuerR = 0;
  fenster = 0;
  haube = 0;
  koffer = 0;
  fach = 0;
  tempo = 0;
  ziel = 0;
  lenk = 0;
  lenkZiel = 0;
  api.showText('Oldtimer — E: Türen, Fenster, Haube, Kofferraum · M: Motor · L: Licht · H: Hupe · Pfeiltasten: fahren', 8);
});
api.on('partInteract', async () => {
  if (tuerL == 0) {
    tuerL = 1;
    api.sound("door_open", 100);
    await api.partTurnTo("Door_L", "y", -65, 0.9);
  } else {
    tuerL = 0;
    await api.partTurnTo("Door_L", "y", 0, 0.675);
    api.sound("door_close", 100);
  }
}, "Fahrertür", "Door_L");
api.on('partInteract', async () => {
  if (tuerR == 0) {
    tuerR = 1;
    api.sound("door_open", 100);
    await api.partTurnTo("Door_R", "y", 65, 0.9);
  } else {
    tuerR = 0;
    await api.partTurnTo("Door_R", "y", 0, 0.675);
    api.sound("door_close", 100);
  }
}, "Beifahrertür", "Door_R");
api.on('partInteract', async () => {
  if (haube == 0) {
    haube = 1;
    api.sound("squeak", 100);
    await api.partTurnTo("Hood", "x", -50, 1.2);
  } else {
    haube = 0;
    await api.partTurnTo("Hood", "x", 0, 0.8999999999999999);
    api.sound("thud", 100);
  }
}, "Motorhaube", "Hood");
api.on('partInteract', async () => {
  if (koffer == 0) {
    koffer = 1;
    api.sound("squeak", 100);
    await api.partTurnTo("Trunk_Lid", "x", 65, 1.1);
  } else {
    koffer = 0;
    await api.partTurnTo("Trunk_Lid", "x", 0, 0.8250000000000001);
    api.sound("thud", 100);
  }
}, "Kofferraum", "Trunk_Lid");
api.on('partInteract', async () => {
  if (fach == 0) {
    fach = 1;
    api.sound("click", 100);
    await api.partTurnTo("Glovebox_Door", "x", -70, 0.4);
  } else {
    fach = 0;
    await api.partTurnTo("Glovebox_Door", "x", 0, 0.30000000000000004);
    api.sound("click", 100);
  }
}, "Handschuhfach", "Glovebox_Door");
api.on('partInteract', async () => {
  if (fenster == 0) {
    fenster = 1;
    await api.partMoveTo("Door_L_Glass", 0, -0.42, 0, 1.4);
  } else {
    fenster = 0;
    await api.partMoveTo("Door_L_Glass", 0, 0, 0, 1.4);
  }
}, "Fenster", "Door_L_Glass");
api.on('partInteract', async () => {
  api.broadcast("zuendung");
}, "Motor starten / abstellen", "Steering_Wheel");
api.on('key', async () => {
  api.broadcast("zuendung");
}, "KeyM");
api.on('message', async () => {
  if (motor == 0) {
    motor = 2;
    api.sound("starter", 100);
    await api.wait(1.1);
    api.loopStart("engine", 80);
    api.partSpin("Engine_Fan", "z", 1400);
    motor = 1;
  } else {
    if (motor == 1) {
      motor = 0;
      api.loopStop("engine");
      api.sound("engine_off", 100);
      api.partSpin("Engine_Fan", "z", 0);
    }
  }
}, "zuendung");
api.on('key', async () => {
  api.sound("click", 100);
  if (licht == 0) {
    licht = 1;
    api.partGlow("Headlight_L_Lens", "#fff2c0", 8);
    api.partGlow("Headlight_R_Lens", "#fff2c0", 8);
    api.partGlow("Taillight_L_Lens", "#ff2010", 4);
    api.partGlow("Taillight_R_Lens", "#ff2010", 4);
  } else {
    licht = 0;
    api.partGlow("Headlight_L_Lens", "#fff2c0", 0);
    api.partGlow("Headlight_R_Lens", "#fff2c0", 0);
    api.partGlow("Taillight_L_Lens", "#ff2010", 0);
    api.partGlow("Taillight_R_Lens", "#ff2010", 0);
  }
}, "KeyL");
api.on('key', async () => {
  api.sound("horn", 100);
}, "KeyH");
api.on('tick', async () => {
  ziel = 0;
  lenkZiel = 0;
  if (motor == 1) {
    if (api.keyDown("ArrowUp")) {
      ziel = 7;
    }
    if (api.keyDown("ArrowDown")) {
      ziel = -3;
    }
  }
  if (api.keyDown("ArrowLeft")) {
    lenkZiel = 1;
  }
  if (api.keyDown("ArrowRight")) {
    lenkZiel = -1;
  }
  tempo = tempo + (ziel - tempo) * api.dt() * 1.2;
  lenk = lenk + (lenkZiel - lenk) * api.dt() * 4;
  api.moveForward(tempo * api.dt() * -1);
  api.rotateBy(0, lenk * tempo * api.dt() * 9, 0);
  api.partSpin("Wheel_FL", "x", tempo * 161);
  api.partSpin("Wheel_FR", "x", tempo * 161);
  api.partSpin("Wheel_RL", "x", tempo * 161);
  api.partSpin("Wheel_RR", "x", tempo * 161);
  api.partSetAngle("Wheel_FL", "y", lenk * 28);
  api.partSetAngle("Wheel_FR", "y", lenk * 28);
  api.partSetAngle("Steering_Wheel", "y", lenk * 120);
  api.loopPitch("engine", 100 + Math.abs(tempo) * 18);
});
